/* TUTORIAL_VIEW_START */
function tutorialHomeMarkup(v){v=v||{};const total=+v.total||19,step=Math.min(total,Math.max(1,+v.step||1)),mode=v.mode||"welcome",B=(k,t,c)=>`<button type="button" class="${c}" data-tut="${k}">${t}</button>`;
const rng=r=>{const m=String(r||"").match(/(\d+)\D+(\d+)/);return m?[+m[1],+m[2]]:[+r||0,+r||0]};
const steps=`<ol class="tm-steps">${(v.chapters||[]).map(c=>{const[a,b]=rng(c.range),cur=mode==="resume"&&step>=a&&step<=b,done=mode==="complete"||(v.hasSession&&step>b);return`<li title="${esc(c.description)}"${cur?' aria-current="step"':""}${done?' class="is-done"':""}>${done?"✓ ":""}${esc(c.name)}</li>`}).join("")}</ol>`;
const cuts=`<details${mode==="complete"?" open":""}><summary>常用操作速查</summary><dl>${(v.shortcuts||[]).map(s=>`<dt>${esc(s.name)}</dt><dd>${esc(s.how)}</dd>`).join("")}</dl></details>`;
let t,l,b,a;
if(mode==="complete"){t="练习完成";l=`${total} 步已走完，练习板保留。`;b=`<ul>${(v.checklist||[]).map(x=>`<li>${esc(x)}</li>`).join("")}</ul>`+cuts;a=B("close","关闭","tm-quiet")+'<span class="tm-sp"></span>'+B("review","回看演练","")+B("start","再开练习板","")+B("return","回到原工作区","tm-primary")}
else if(mode==="resume"&&v.canResume){t="继续上次的演练";l=`停在第 ${step} 步：${esc(v.title)}`;b=steps+cuts;a=B("close","关闭","tm-quiet")+B("return","回原工作区","tm-quiet")+'<span class="tm-sp"></span>'+B("start","新开练习板（保留旧板）","")+B("resume",`继续第 ${step} 步`,"tm-primary")}
else{t="用一次虚构流程学会 Relay";l="在独立练习板里搭项目、配成员、发任务、连线和复盘，原画板不受影响。";b=steps;a=B("close","稍后","tm-quiet")+'<span class="tm-sp"></span>'+(v.hasSession?B("coach","展开当前步",""):"")+B("start","开始练习","tm-primary")}
return`<div class="tm-home">${piece("claude",40,true)}<h2>${esc(t)}</h2><p class="tm-lede">${l}</p><p class="tm-safe">本地演练 · 无需 API · 不真实发布</p>${b}<div class="tm-acts">${a}</div></div>`}
function tutorialCoachMarkup(v){v=v||{};const total=+v.total||19,step=Math.min(total,Math.max(1,+v.step||1)),menu=`<button type="button" class="tm-quiet" data-tut="menu" aria-label="教程目录" title="目录">${icon("board",15)}</button>`;
if(v.collapsed)return`<button type="button" data-tut="expand" aria-label="展开教程第 ${step}/${total} 步"><b>${step}/${total}</b><span>${esc(v.title)}</span></button>${menu}`;
const head=`<div class="tm-head"><span>${step}/${total} · ${esc(v.chapter)}</span><span class="tm-sp"></span>${menu}<button type="button" class="tm-quiet" data-tut="collapse" aria-label="收起教练卡">–</button></div><div class="tm-bar" role="progressbar" aria-valuemin="1" aria-valuemax="${total}" aria-valuenow="${step}"><i style="width:${Math.round(step/total*100)}%"></i></div>`;
const pause=`<button type="button" class="tm-quiet" data-tut="pause">暂停</button>`;
if(v.away)return head+`<div class="tm-body"><h3>${esc(v.title)}</h3><p>你在原画板，教程不会改动这里。</p></div><div class="tm-foot"><button type="button" class="tm-primary" data-tut="resume">返回练习板</button>${pause}</div>`;
const checks=v.checklist?`<ul class="tm-checks">${(v.checks||[]).map((c,i)=>`<li><label for="tut-chk-${i}"><input type="checkbox" id="tut-chk-${i}" data-tut-check="${esc(c.id)}"${c.checked?" checked":""}><span>${esc(c.label)}</span></label></li>`).join("")}</ul>`:"";
const body=`<h3>${esc(v.title)}</h3><p>${esc(v.description)}</p>${checks}${v.tip||v.why?`<details><summary>提示与原因</summary>${v.tip?`<p class="tm-tip">${esc(v.tip)}</p>`:""}${v.why?`<p class="tm-tip">${esc(v.why)}</p>`:""}</details>`:""}${v.error?`<p class="tm-err" role="alert">${esc(v.error)}</p>`:""}${v.done&&v.result?`<p class="tm-ok" role="status">✓ ${esc(v.result)}</p>`:""}`;
const act=v.actionLabel&&!v.done?`<button type="button" data-tut="action"${v.busy?' disabled aria-busy="true"':""}>${esc(v.busy?"处理中…":v.actionLabel)}</button>`:"";
return head+`<div class="tm-body">${body}${act?`<details class="tutorial-example"><summary>使用内置练习示例</summary><p class="lab">可选择示范；编号箭头指向软件里的实际操作位置。</p>${act}</details>`:""}</div><div class="tm-foot"><button type="button" class="tm-quiet" data-tut="previous"${v.canPrevious?"":" disabled"}>上一步</button><span class="tm-sp"></span>${pause}<button type="button" class="tm-primary" data-tut="next"${v.done?"":' disabled title="完成当前任务后可继续"'}>${step===total?"完成":"下一步"}</button></div>`}
function tutorialLauncherMarkup(v){v=v||{};const total=+v.total||19,step=+v.step||1;if(v.status==="complete")return`${icon("help",16)}<span>教程与速查</span>`;if(v.hasSession)return`${icon("help",16)}<span>继续演练</span><span class="tm-n">${step}/${total}</span>`;return`${icon("help",16)}<span>新手教程</span>`}
/* TUTORIAL_VIEW_END */
